import unreal, json
actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors()
report = {'landscapes': [], 'mesh_assets': []}
for a in actors:
    if not isinstance(a, unreal.LandscapeProxy): continue
    row = {'actor': a.get_actor_label(), 'components': []}
    for prop in ['landscape_material', 'landscape_guid', 'landscape_layers']:
        try: row[prop] = str(a.get_editor_property(prop))
        except Exception as e: row[prop] = str(e)
    for c in a.get_components_by_class(unreal.LandscapeComponent):
        comp = {'name': c.get_name()}
        for prop in ['section_base_x', 'section_base_y', 'component_size_quads', 'weightmap_layer_allocations', 'weightmap_textures']:
            try: comp[prop] = str(c.get_editor_property(prop))
            except Exception as e: comp[prop] = str(e)
        row['components'].append(comp)
    report['landscapes'].append(row)
ar = unreal.AssetRegistryHelpers.get_asset_registry()
for asset in ar.get_assets_by_path('/Game', recursive=True):
    if 'splatmap_testing2' in str(asset.asset_name).lower(): report['mesh_assets'].append({'name': str(asset.asset_name), 'package': str(asset.package_name), 'class': str(asset.asset_class_path)})
print(json.dumps(report, indent=2))
